package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.io.Base64Variant;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.BooleanNode;
import com.fasterxml.jackson.databind.node.IntNode;
import com.fasterxml.jackson.databind.node.NullNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.node.POJONode;
import com.fasterxml.jackson.databind.node.TextNode;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TreeTraversingParser_getBinaryValue_TriageGen0Test {

    private final ObjectMapper mapper = new ObjectMapper();

    @Test
    public void testGetBinaryValue_NullNode() throws IOException, JsonParseException {
        // currentNode() returns null
        TreeTraversingParser parser = new TreeTraversingParser(null);
        byte[] result = parser.getBinaryValue(Base64Variant.of(""));
        Assert.assertNull(result);
    }

    @Test
    public void testGetBinaryValue_BinaryNode() throws IOException, JsonParseException {
        // Create a node that behaves like a BinaryNode via coercion or direct content
        // In Jackson, TextNode with Base64 content often returns byte[] via binaryValue()
        String base64Data = "SGVsbG8="; // "Hello"
        TextNode textNode = mapper.getNodeFactory().textNode(base64Data);

        TreeTraversingParser parser = new TreeTraversingParser(textNode);
        byte[] result = parser.getBinaryValue(Base64Variant.of(""));

        Assert.assertNotNull(result);
        Assert.assertArrayEquals("Hello".getBytes(), result);
    }

    @Test
    public void testGetBinaryValue_TextNodeReturningNullBinary() throws IOException, JsonParseException {
        // A text node that is not valid base64 or results in null binaryValue()
        // Note: n.binaryValue() usually returns null for non-binary nodes if not coerced
        TextNode textNode = mapper.getNodeFactory().textNode("not-base64-logic-trigger");

        // We simulate the case where n.binaryValue() is null but n is not a POJO
        TreeTraversingParser parser = new TreeTraversingParser(textNode);

        // If binaryValue() returns null and it's not a POJO, it returns null
        // This depends on Jackson's implementation of binaryValue() on TextNode
        // If TextNode.binaryValue() returns null, we check the branch
        byte[] result = parser.getBinaryValue(Base64Variant.of(""));

        // If the text node doesn't qualify as binary via binaryValue(), it returns null
        if (textNode.binaryValue() == null) {
            Assert.assertNull(result);
        } else {
            Assert.assertNotNull(result);
        }
    }

    @Test
    public void testGetBinaryValue_PojoNodeWithByteArray() throws IOException, JsonParseException {
        // Create a POJONode containing a byte[]
        byte[] expectedData = new byte[]{1, 2, 3, 4};
        POJONode pojoNode = new POJONode(expectedData);

        TreeTraversingParser parser = new TreeTraversingParser(pojoNode);
        byte[] result = parser.getBinaryValue(Base64Variant.of(""));

        Assert.assertArrayEquals(expectedData, result);
    }

    @Test
    public void testGetBinaryValue_PojoNodeWithNonByteArray() throws IOException, JsonParseException {
        // Create a POJONode containing something else (e.g., a String)
        POJONode pojoNode = new POJONode("not a byte array");

        TreeTraversingParser parser = new TreeTraversingParser(pojoNode);
        byte[] result = parser.getBinaryValue(Base64Variant.of(""));

        Assert.assertNull(result);
    }

    @Test
    public void testGetBinaryValue_NonBinaryNonPojoNode() throws IOException, JsonParseException {
        // Use an IntNode: n != null, n.binaryValue() is null, n.isPojo() is false
        IntNode intNode = mapper.getNodeFactory().numberNode(123);

        TreeTraversingParser parser = new TreeTraversingParser(intNode);
        byte[] result = parser.getBinaryValue(Base64Variant.of(""));

        Assert.assertNull(result);
    }

    @Test
    public void testGetBinaryValue_NullNodeInObject() throws IOException, JsonParseException {
        // Test with NullNode
        NullNode nullNode = NullNode.getInstance();
        TreeTraversingParser parser = new TreeTraversingParser(nullNode);
        byte[] result = parser.getBinaryValue(Base64Variant.of(""));

        Assert.assertNull(result);
    }
}
